// Define the RandomState struct to hold the seed
#[derive(Copy, Clone)]
pub struct RandomState {
    seed: u8,
}

impl RandomState {
    // Constructor to create a new RandomState with a given seed
    pub fn new(seed: u8) -> Self {
        RandomState { seed }
    }
}

// The random function that returns a deterministic pseudo-random f32 in [0, 1)
pub fn random(state: RandomState) -> f32 {
    // Map the seed modulo 8 to one of eight equally spaced values
    match state.seed % 8 {
        0 => 0.0,
        1 => 0.125,
        2 => 0.25,
        3 => 0.375,
        4 => 0.5,
        5 => 0.625,
        6 => 0.75,
        7 => 0.875,
        _ => unreachable!(), // This case is impossible due to modulo 8
    }
}

